CREATE OR REPLACE FUNCTION lab.nth_pos (p_text varchar, p_find varchar, p_nth numeric)
RETURNS numeric
LANGUAGE plpgsql
SET search_path = lab, public
AS $$
DECLARE
  v_pos  integer := 0;
  v_from integer := 1;
  v_hit  integer;
BEGIN
  IF p_text IS NULL OR p_find IS NULL OR p_nth IS NULL THEN
    RETURN NULL;
  END IF;
  FOR i IN 1 .. trunc(p_nth)::integer LOOP
    v_hit := strpos(substr(p_text, v_from), p_find);
    IF v_hit = 0 THEN
      RETURN 0;
    END IF;
    v_pos := v_from + v_hit - 1;
    v_from := v_pos + 1;
  END LOOP;
  RETURN v_pos;
END;
$$;
